window.__BUNDLE__={"generatedAt":"2026-10-01T18:38:38.255582+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-24","archiveCutoff":"2021-10-02","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":260,"arxiv":1983,"total":2243},"freshness":{"latestPaperDate":"2026-10-01","latestPublishedDate":"2026-10-01","latestBatchCount":516,"newInLast24h":556,"newInLast48h":1237},"historyTotal":19540,"topicCounts":{"Multi-Agent":2422,"Evaluation":10536,"Planning":1531,"Memory":399,"Code Agent":780,"Interpretability":705,"Agentic RAG":1284,"Agentic Search":1639,"RL for LLM":1135,"Reasoning":5490,"Hallucination":996,"Post-Training":2280,"Alignment":2618,"World Model":314,"Tool Use":1244,"Agent Safety":2372,"Computer Use":290,"Reflection":702,"VLM Training":1436,"LLM Training":2384,"Fine-tuning":2991,"Multimodal Agent":113,"Agent Framework":812,"Error Attribution":122,"Data Engine":390},"count":36,"recentTotal":3427,"archiveCount":0,"archiveTotal":16113,"sources":{"hf":104,"arxiv":3323,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"upvotes":178,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Fang Wu","Da Xing","Yanjie Huang","Junxi Wang","Ji Wang","Hejia Geng","Guancheng Wan","Bowen Zuo","Xiaomin Li","Shixiang Tang","Xinyu Xiang","Zehong Wang","Shiyi Du","Peng Xia","Shuangjia Zheng","Yining Hong","Li Erran Li","Jure Leskovec","Yejin Choi"],"url":"https://arxiv.org/abs/2609.38721","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.38721","topics":["Reflection"],"source":"hf","title":"UniEvo-VL: An On-policy Self-Distillation Training Recipe for Multimodal Model Self-improvement","pdf":"https://arxiv.org/pdf/2609.38721.pdf","tags":["Reflection"],"hfUrl":"https://huggingface.co/papers/2609.38721","id":"arxiv:2609.38721","abstract":"Modern multimodal models bring generation and understanding into a single unified system, which enables them to provide and learn from their own feedback. Motivated by this unified capacity, we introduce UniEvo-VL, a self-evolving framework for multimodal models to learn from this constructive self-correction feedback during test-time compute. Instead of relying on a separate, often larger, teacher, we leverage their self-critiques as privileged information and ask a single multimodal model to act as both teacher and student with different contexts. The student only sees the vanilla question, while the teacher conditions on the privileged critique. Then training minimizes the per-state divergence between their denoising diffusion distributions over the student's own sampling trajectories. Experiments demonstrate that UniEvo-VL improves the image generation capabilities of multimodal mode"},{"upvotes":159,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Meijia Chen","Hao Li","Zheng Lu","Hongshan Lin","Junbai Tian","Yichen Liu","Zijun Tian","Yufan Zou","Shuhan Sun","Hanxin Chen","Zeyu Zhang","Weizhi Du","Yueting Li","Tianyu Shi","Alaa Khamis"],"url":"https://arxiv.org/abs/2609.39102","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39102","topics":["Agentic Search","Evaluation"],"source":"hf","title":"False Frontiers: Diagnosing and Mitigating Co-Cheating in Self-Evolving Search Agents","pdf":"https://arxiv.org/pdf/2609.39102.pdf","tags":["Agentic Search","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.39102","id":"arxiv:2609.39102","abstract":"Self-evolving search agents build their own training curricula by jointly optimizing a proposer that generates questions and a solver that answers them. This closed loop introduces a failure mode we call co-cheating: the proposer and solver increasingly agree on shared errors, so internal reward improves without a matching gain in external correctness. A post-hoc audit against source evidence shows co-cheating growing more severe over successive rounds of self-evolution, with pseudo-label correctness stagnating or declining even as the in-loop training signal improves. The most direct mitigation is to verify proposals before training: we introduce multi-sample verification (MSV), which queries the same model three times with the source and three times without it to decide task admission and replace unreliable pseudo-labels. MSV partially reduces false agreement but leaves substantial res"},{"upvotes":107,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Hongjin Qian","Chaofan Li","Kun Luo","Wenqing Wei","Jianlyu Chen","Shuqi Lu","Yuyang Hu","Hongwang Xiao","Hui Wang","Chaozhuo Li","Qiwei Ye","Zhicheng Dou","Defu Lian","Zheng Liu"],"url":"https://arxiv.org/abs/2609.38288","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38288","topics":["Reflection"],"source":"hf","title":"AREX-2: Advancing Self-Improving Agents through Long-Horizon Reflective Tasks","pdf":"https://arxiv.org/pdf/2609.38288.pdf","tags":["Reflection"],"hfUrl":"https://huggingface.co/papers/2609.38288","id":"arxiv:2609.38288","abstract":"We present AREX-2, an effort to advance the self-improving capability of LLM agents, which we define as the ability to iteratively refine a solution at test time. This ability rests on two complementary capabilities: reflection, which produces a solution better than the current one, and long-horizon execution, which keeps the iteration effective over many rounds. We hypothesize that both capabilities are domain-agnostic, and can therefore be learned in scenarios that are well suited for supervision. Accordingly, we synthesize long-horizon improvement trajectories from machine learning and algorithmic programming tasks, two domains that offer verifiable feedback and reward sustained iteration. Trained on this data, our agent, built on Qwen3.8-27B, achieves strong results on MLE-bench Lite (81.8) and Frontier-CS (70.7), transfers to deep research with 84.0 on BrowseComp, 52.6 on HLE, 92.2 "},{"upvotes":86,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Minki Kang","Ryo Hachiuma","Shaokun Zhang","Subhashree Radhakrishnan","Yonggan Fu","Jindong Jiang","Mingjie Liu","Ehsan Hosseini-Asl","Yi Dong","Yu-Chiang Frank Wang","Byung-Kwan Lee"],"url":"https://arxiv.org/abs/2609.39982","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39982","topics":["Evaluation"],"source":"hf","title":"Mid-Harness: Scaling Actions Between Model and Harness for Terminal Agents","pdf":"https://arxiv.org/pdf/2609.39982.pdf","tags":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.39982","id":"arxiv:2609.39982","abstract":"Terminal agents act through stochastic model generations, yet the ability to generate a useful action does not ensure its reliable execution. A poor command (e.g., wrong package install) can change the environment in ways that hinder subsequent progress, even when the model could generate a better alternative. We investigate whether allocating test-time compute at the model-harness boundary can improve action reliability and trajectory success, and what makes this allocation effective. To study these questions, we introduce Mid-Harness, which samples and verifies candidate actions before forwarding one for execution, while keeping the generator and harness unchanged. With a TMAX-9B generator, more action sampling yields little benefit under weak verification, whereas a capable verifier can exploit useful alternatives from the same generator. On TerminalBench-Lite, a GPT-5.6 Sol verifier "},{"upvotes":75,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Ziyan Jiang","Jingbo Yang","Jiabao Ji","Yujian Liu","Qiucheng Wu","Tommi Jaakkola","Yang Zhang","Shiyu Chang"],"url":"https://arxiv.org/abs/2609.40325","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.40325","topics":["VLM Training","Reasoning","Evaluation","Multimodal Agent"],"source":"hf","title":"WorldAuditBench: Interactive 3D World Auditing with Multimodal Agents","pdf":"https://arxiv.org/pdf/2609.40325.pdf","tags":["VLM Training","Reasoning","Evaluation","Multimodal Agent"],"hfUrl":"https://huggingface.co/papers/2609.40325","id":"arxiv:2609.40325","abstract":"As interactive 3D worlds are increasingly used to study intelligent behavior, it becomes important to develop efficient pipelines for identifying anomalies in these simulated environments, such as floating objects, traversable walls, or objects inconsistent with the surrounding scene. Multimodal AI systems, including vision-language models (VLMs) and vision-language-action models (VLAs), have shown potential for automating this task. However, 3D world auditing is complex, requiring the close coupling of two distinct capabilities: action, to navigate the 3D world and search for anomalies systematically and efficiently; and visual reasoning, to understand the environment and identify anomalies from multimodal observations. It remains largely unexplored whether multimodal agents can effectively couple these two capabilities, using visual reasoning to identify potential anomalies while takin"},{"upvotes":49,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Yuhan Guo","Jinming Liu","Liang Xu","Ziqiang Li","Jianguo Huang","Zhicheng Wang","Hu Zhu","Qiuyu Chen","Yuntao Wei","Xin Jin","Wenjun Zeng"],"url":"https://arxiv.org/abs/2609.38334","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38334","topics":["Post-Training","LLM Training","Planning","World Model"],"source":"hf","title":"EVOKE: Eliciting World Knowledge in Agents for Transferable Decision-Making","pdf":"https://arxiv.org/pdf/2609.38334.pdf","tags":["Post-Training","LLM Training","Planning","World Model"],"hfUrl":"https://huggingface.co/papers/2609.38334","id":"arxiv:2609.38334","abstract":"Large language models (LLMs) are increasingly deployed as agents for multi-step decision-making, yet transfer poorly to unseen environments. World-model methods address this by training agents to predict future observations, at the cost of additional training and errors that compound when predictions are used for planning. However, for LLM agents operating in digital environments, much of this world knowledge is already internalized during pretraining, which shifts the problem from acquiring it to eliciting it. We argue that typical post-training provides little pressure for such elicitation, since supervision under a single goal at each visited state inadvertently drives policies to rely on superficial contextual habits. We introduce EVOKE, a post-training method that supplies this pressure through goal diversity at fixed states. Motivated by theory showing that an agent competent acros"},{"upvotes":41,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Tianxiang Gao","Jinzhe Li","Zhiyuan Li","Yi Chang","Yuan Wu"],"url":"https://arxiv.org/abs/2609.38827","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.38827","topics":["Post-Training","Evaluation","Fine-tuning"],"source":"hf","title":"More Choices, Fewer Decisions: Ordinal-Scale Bias in JEV-like Direct-Decision Models","pdf":"https://arxiv.org/pdf/2609.38827.pdf","tags":["Post-Training","Evaluation","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2609.38827","id":"arxiv:2609.38827","abstract":"Direct-decision models turn text into low-latency structured labels and scores, making them attractive for classification and automatic evaluation. Yet reliability requires more than accuracy: a model must also use the ordinal decision scale supplied by the user faithfully. We analyze JEV~1.13 and three open KEV models. Our investigation begins with ANLI, where JEV assigns 38.8\\% of all predictions and 51.3\\% of errors to Neutral despite 74.95\\% accuracy, nearly balanced gold labels, and balanced candidate positions. Across 36 ordinal datasets, final decisions use only 67--76\\% of the effective gold support, versus 87--102\\% on four nominal tasks. Randomizing candidate order weakens but does not remove this compression. Holding items and source scores fixed while balancing gold support and positions, we refine scales from $K=2$ to $14$; utilization falls for every model and reaches 26--7"},{"upvotes":39,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Wenyi Wu","Minghao Fu","Jieyu You","Kun Zhou","Siqi Liu","Aayush Salvi","Yiheng Lin","Ce Zhang","Xiaohan Lan","Jiahui Zhu","Yujie Zhong","Qi She","Biwei Huang"],"url":"https://arxiv.org/abs/2609.39045","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39045","topics":["Reflection"],"source":"hf","title":"RSIGame: Autonomous Agentic Game Development with Recursive Self-improvement","pdf":"https://arxiv.org/pdf/2609.39045.pdf","tags":["Reflection"],"hfUrl":"https://huggingface.co/papers/2609.39045","id":"arxiv:2609.39045","abstract":"Recent advances in large language models have made automatic game generation increasingly feasible, yet reliably improving generated games beyond a playable version remains challenging. Naive iterative refinement can easily overfit a small set of test cases, producing fragile games with unresolved bugs, missing behaviors, and poor generalization to broader player interactions. We introduce RSIGame, an autonomous agentic game development framework with recursive self-improvement. RSIGame organizes development into complementary local and global loops. Concretely, a local explore-diagnose-improve loop broadly explores the executable game, diagnoses and prioritizes discovered issues, and performs evidence-grounded revision, where an evolving checklist continually accumulates new testing and improvement guidance. A global loop tracks overall quality, preserves the best checkpoint, and detect"},{"upvotes":36,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Hyeong Kyu Choi","Bhavana Dalvi Mishra","Jiefeng Chen","Mihir Parmar","Rui Meng","Chun-Liang Li","Xiangru Tang","Sharon Li","Jinsung Yoon","Tomas Pfister"],"url":"https://arxiv.org/abs/2609.38445","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38445","topics":["Evaluation","Alignment"],"source":"hf","title":"AIM: Agentic Idea Management for Automated Research","pdf":"https://arxiv.org/pdf/2609.38445.pdf","tags":["Evaluation","Alignment"],"hfUrl":"https://huggingface.co/papers/2609.38445","id":"arxiv:2609.38445","abstract":"Frontier LLMs are increasingly used to automate scientific research through iterative search. We distinguish idea-driven search from solution-driven search and identify three core challenges: organizing evolving research ideas, selecting promising directions, and maintaining alignment between ideas and their implementations. To address these challenges, we introduce the Agentic Idea Manager (AIM), a fully autonomous framework for managing and exploring research directions in idea-driven automated research. Inspired by Bayesian optimization, AIM uses an Agentic Surrogate and an Agentic Acquisition mechanism to organize discovered ideas and guide their selection. A Solution Auditor maintains idea-solution integrity, while a Resource Planner adaptively allocates the remaining experimental budget across parallel search branches. Experiments on 10 AutoLab benchmark tasks show that AIM surpass"},{"upvotes":35,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Minghan Wang","Boyuan Wang","Jinhang Zuo","Yuxin Tao","Fang kong"],"url":"https://arxiv.org/abs/2609.39578","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39578","topics":["Agent Safety","LLM Training","Evaluation","Fine-tuning"],"source":"hf","title":"Thinking Outside the Box: Can Language Models Rely on External Guidance Selectively?","pdf":"https://arxiv.org/pdf/2609.39578.pdf","tags":["Agent Safety","LLM Training","Evaluation","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2609.39578","id":"arxiv:2609.39578","abstract":"Agent harnesses often improve language models with human-designed workflows, but as models grow more capable, unreliable guidance can increasingly constrain their execution. We call the ability to benefit from useful guidance while overriding unreliable guidance thinking outside the box. We introduce Box$^2$-Bench, which holds the model and task fixed while varying workflow reliability to isolate how models regulate their reliance on guidance. On Box$^2$-Bench, frontier models often benefit from reliable guidance but remain vulnerable when it is misleading or becomes unreliable. To test whether this capability can be learned, we train two open-weight models using bad workflows, reserving good workflows for evaluation. We explore two complementary training strategies: counterfactual supervised fine-tuning improves robustness, while outcome-based reinforcement learning can shift the balanc"},{"upvotes":34,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Kunlun Zhu","Xuyan Ye","Yibo Li","Cheng Qian","Beibin Li","Heng Ji"],"url":"https://arxiv.org/abs/2609.40111","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.40111","topics":["Post-Training","Fine-tuning"],"source":"hf","title":"Agent Error Dataset: Scaling 50,000 Error--Diagnosis Pairs for Failure Analysis and Error-Aware Post-Training","pdf":"https://arxiv.org/pdf/2609.40111.pdf","tags":["Post-Training","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2609.40111","id":"arxiv:2609.40111","abstract":"An unsuccessful LLM agent rollout contains more information than its final reward: the observations available to the agent, the actions it chose, and the environment's responses. Reusing this experience for learning requires identifying a decision to revise and testing a concrete alternative. We introduce the Agent Error Dataset (AED), comprising 50,228 error-diagnosis pairs from 9,961 source tasks across 33 environments, 19 harness families, and 23 policy models in text-based agent systems. We retain source traces and execution metadata to support cross-setting failure analysis and re-diagnosis without repeating the original rollout. Our five-stage Agentic Error-to-Training (AET) pipeline collects natural failures, generates diagnoses and proposed corrections, and checks them against recorded evidence. Where replay is supported, we compare corrections with original-action retries from t"},{"upvotes":28,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Haibo Jin","Xinjie Li","Najmeh Sadoughi","Yang Liu","Yibo Wang","Zhu Liu","Yuzong Liu"],"url":"https://arxiv.org/abs/2609.38660","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38660","topics":["Multi-Agent","Reasoning","Evaluation"],"source":"hf","title":"Breaking Babel: A Self-Evolving Multi-Agent System for Long-Form Subtitle Translation","pdf":"https://arxiv.org/pdf/2609.38660.pdf","tags":["Multi-Agent","Reasoning","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.38660","id":"arxiv:2609.38660","abstract":"Long-form subtitle translation requires reasoning over discourse and cultural context spanning episodes or entire series, while maintaining consistent terminology and style. Existing single-LLM methods are largely sentence-level, and multi-agent systems often use static workflows that do not adapt to scene complexity or production context. We propose SMART, a Self-evolving Multi-Agent system for long-foRm subtitle Translation. During test-time training, SMART builds persistent series-level memory and translates a subset of sentences through a dynamic router and Mixture-of-Agents layer with tools for terminology verification, subtitle constraint validation, and contextual retrieval. A judge-refiner loop scores candidates and uses textual critiques to update agent prompts and routing policies without retraining the underlying LLMs. During test-time inference, the evolved configuration tran"},{"upvotes":18,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Donghao Zhou","Haoyang He","Fan Zhang","Hao Yang","Guisheng Liu","Xin Gao","Zhongwei Wan","Xingyuan Bu","Jie Wang","Qiangpeng Yang","Shilei Wen","Chi-Wing Fu","Pheng-Ann Heng"],"url":"https://arxiv.org/abs/2609.38541","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38541","topics":["Reasoning","Evaluation"],"source":"hf","title":"ThinkV2V: Unleashing the Reasoning Capability of MLLMs for Instruction-Guided Video Editing","pdf":"https://arxiv.org/pdf/2609.38541.pdf","tags":["Reasoning","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.38541","id":"arxiv:2609.38541","abstract":"Instruction-guided video editing has made significant progress, yet existing methods use multimodal large language models (MLLMs) primarily as semantic encoders, so they often fall short in working with implicit edits that require causal or semantic reasoning. To bridge this fundamental gap in video editing, we propose ThinkV2V, a reasoning-driven framework for complex instruction-guided video editing, explicitly activating MLLM thinking before visual generation. At its core, ThinkV2V builds on a practical MLLM-to-DiT architecture to turn explicit thinking over the source video and instruction into refined conditioning signals for video editing. Further, we equip it with a dedicated training and inference recipe, combining Progressive Curriculum Training, which gradually cultivates the model from basic editing to reasoning-intensive cases, with Inference-Time Thinking Scaling, which iter"},{"upvotes":16,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Zhe Qian","Ziyang Gong","Zhongxing Xu","Hehan Li","Zhonghua Wang","Fei Luo","Mingxuan Wang","Xue Yang","Shiwei liu","Yanbiao Ma","Junchi Yan","Jungong Han"],"url":"https://arxiv.org/abs/2609.38426","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38426","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation"],"source":"hf","title":"LoopVL: Recurrent Visual Intelligence","pdf":"https://arxiv.org/pdf/2609.38426.pdf","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.38426","id":"arxiv:2609.38426","abstract":"We introduce LoopVL to study whether Loop Transformers can be effectively extended to vision- language models. LoopVL combines Module-Loop and Model-Loop computation to iteratively update a unified vision-language state through shared modules. We train LoopVL from scratch through language pre-training, multimodal training, and post-training. LoopVL outperforms a range of similarly sized and larger non-recurrent models on multimodal understanding and visual reasoning benchmarks. We also observe Visual Aha Moments in LoopVL, characterized by pronounced shifts in visual attention across loops. LoopVL provides practical evidence for recurrent vision-language modeling and offers an intuitive perspective on how shared parameters can support deeper multimodal computation over continuously evolving visual-language states."},{"upvotes":15,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Dingyuan Dai","Heli Qi","Lei Liu","Yinxi Li","Baiding Chen","Zijun Dou","Qingcheng Zeng","Qi Kang","Oliver Sun","Eric Wang","Bo Zhou","Haixin Wang","Yufan Du","Shi Bo","Ruihan Lin","Mengqi Yuan","Dunjie Lu","Steven Dillmann","Yiming Shi","Tina Su","Amy Xin","Minghao Liu","Xi Wang","Xu Huang","Ge Zhang","Pengyu Nie","Zhen Yang","Jie Tang","Juanzi Li","Weihao Xuan","Tianyu Liu"],"url":"https://arxiv.org/abs/2609.39903","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39903","topics":["Reasoning","Computer Use","Evaluation"],"source":"hf","title":"OSWorld-Science: A Benchmark of Computer Use Agents for Learning and Using Scientific Software","pdf":"https://arxiv.org/pdf/2609.39903.pdf","tags":["Reasoning","Computer Use","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.39903","id":"arxiv:2609.39903","abstract":"Scientific software presents a demanding test for computer-using agents based on visual language models (VLMs): completing a research workflow requires interpreting specialized interfaces, manipulating scientific objects, and producing verifiable results. We thus introduce OSWorld-Science, a benchmark and evaluation environment that combines scientifically meaningful tasks, artifact-based evaluation, and an efficient agent harness for studying computer use in the scientific domain. The benchmark contains 12 VLMs and 146 high-quality tasks across several scientific domains and software configurations, covering workflows such as molecular drawing and retrosynthesis, pathology image analysis, statistical computing, and physical simulation. Tasks are developed through expert proposals and iterative human--AI co-design, with selection guided by scientific value and difficulty. Task-specific e"},{"upvotes":12,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Langlin Huang","Hao Liu","Mononito Goswami","Xinyu Li","Prithwith Jana","Nikos Kanakaris","Patrick Blöbaum","Purak Jain"],"url":"https://arxiv.org/abs/2609.38360","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38360","topics":["Post-Training","Reasoning","RL for LLM"],"source":"hf","title":"On the Off-Policy Teacher in On-Policy Distillation","pdf":"https://arxiv.org/pdf/2609.38360.pdf","tags":["Post-Training","Reasoning","RL for LLM"],"hfUrl":"https://huggingface.co/papers/2609.38360","id":"arxiv:2609.38360","abstract":"On-policy distillation (OPD) has recently emerged as a promising post-training paradigm in which the student learns from trajectories generated by its own policy under dense teacher supervision. However, OPD introduces a fundamental asymmetry: although the sampled trajectories are on-policy for the student, they are off-policy for the teacher. The teacher is typically optimized to continue from prefixes generated by its own policy, but during OPD it must instead supervise prefixes generated by the student. Empirically, we find that its continuation performance degrades as these prefixes grow longer. To address this issue, we propose Student-COnditioned Updates of the Teacher (SCOUT), a co-training framework that adapts the teacher to student-generated prefixes. Alongside standard OPD updates, SCOUT periodically optimizes the teacher's conditional ability using reinforcement learning with"},{"upvotes":10,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Yanbei Chen","Anirudh Goyal","Raghuraman Krishnamoorthi"],"url":"https://arxiv.org/abs/2609.40316","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.40316","topics":["LLM Training","Reasoning","Evaluation"],"source":"hf","title":"Scaling Laws for Looped Mixture of Experts","pdf":"https://arxiv.org/pdf/2609.40316.pdf","tags":["LLM Training","Reasoning","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.40316","id":"arxiv:2609.40316","abstract":"Looped transformers and Mixture-of-Experts (MoE) offer complementary routes to efficient scaling: recurrence increases computational depth at fixed parameters, while MoE sparsity expands total capacity at fixed active compute. Yet existing scaling laws model recurrence or sparsity in isolation. In this work, we introduce Loop Scaling Laws, the first scaling law to jointly model recurrence and sparsity alongside model size and data. At its core is a bounded, sparsity-conditional recurrence mapping that characterizes the effective-parameter gain from looping and how sparsity raises this gain. The laws predict the held-out loss of looped models more accurately than prior alternatives, and recover the standard dense and MoE scaling laws as special cases. Beyond prediction, the fitted laws provide a principled foundation for designing looped MoE models under compute and memory constraints. Do"},{"upvotes":7,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Liming Lu","Xianzheng Ma","Wenkun He","Guanqi Zhan","Yilin Zhao","Junyu Chen","Mengyao Xu","Jiaojiao Fan","Wenhang Ge","Yuchao Gu","Yunze Liu","Boyi Li","Zhen Dong","Victor Prisacariu","Ming-Yu Liu","Song Han","Han Cai"],"url":"https://arxiv.org/abs/2609.40358","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.40358","topics":["Planning","Evaluation","World Model"],"source":"hf","title":"Physis-Lang: Self-Evolving Language as a Physical Representation for Video World Model","pdf":"https://arxiv.org/pdf/2609.40358.pdf","tags":["Planning","Evaluation","World Model"],"hfUrl":"https://huggingface.co/papers/2609.40358","id":"arxiv:2609.40358","abstract":"Video world models are expected to predict how the physical world evolves, yet they often produce visually plausible videos that violate basic physical principles. Existing approaches commonly assume that natural language is insufficient to represent the physical knowledge required for reliable generation, and therefore introduce additional visual, latent, numerical, or planning-based signals. We revisit this assumption and introduce Physis-Lang, a self-evolving framework that treats physical language as a shared and optimizable representation across data curation, model training, and video generation. Physis-Lang represents physical processes through language that describes their relevant entities, causes, interactions, governing principles, temporal evolution, and effects. To improve this representation, we construct PhysCapBench, which decomposes physical processes into atomic asserti"},{"upvotes":6,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Atsuki Yamaguchi","Tatsuro Inaba","Joel Niklaus","Michal Štefánik","Aline Villavicencio","Nikolaos Aletras"],"url":"https://arxiv.org/abs/2609.39827","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39827","topics":["LLM Training"],"source":"hf","title":"Synthetic Pre-pretraining Survives Scale, but Not as a Grammatical Prior","pdf":"https://arxiv.org/pdf/2609.39827.pdf","tags":["LLM Training"],"hfUrl":"https://huggingface.co/papers/2609.39827","id":"arxiv:2609.39827","abstract":"Pre-pretraining (PPT) on synthetic non-natural language data improves token efficiency during language model pre-training (PT). Prior work attributes this gain to a grammatical prior, i.e., a structural inductive bias learned during PPT that transfers to natural language grammar. However, PPT has only been tested on models of at most 1B parameters and PT budgets below 2B tokens on predominantly web text. It is unknown whether PPT is effective at larger scales and under more realistic PT data mixtures that combine diverse sources (e.g., code and math). We therefore present a comprehensive study on PPT spanning five PPT tasks, four PT data mixtures, four parameter scales (500M to 7B), and PT budgets of up to 100B tokens. Our results demonstrate that the downstream performance and token efficiency gains of PPT persist at scale, e.g., saving at least 21B PT tokens at the 3B scale. However, i"},{"upvotes":5,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Seonho Lee","Wonryeol Jeong","Alberto Cereser","Inha Kang","Hyeonjong Kim","Seungmin Kwak","Dongmin Park"],"url":"https://arxiv.org/abs/2609.39564","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39564","topics":["Code Agent","Evaluation"],"source":"hf","title":"A2Z GameSpec-Bench: How Faithfully Can Coding Agents Generate Games from Game Design Specifications?","pdf":"https://arxiv.org/pdf/2609.39564.pdf","tags":["Code Agent","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.39564","id":"arxiv:2609.39564","abstract":"Delegating complete application development to coding agents requires preserving the intended design rather than simply producing plausible outputs through naive prompting. Game development provides a demanding testbed, as long-form Game Design Documents (GDDs) describe requirements that must work together across game logic, visual rendering, and player interactions. However, existing game-development benchmarks typically use compact specifications and provide limited support for evaluating interdependent requirements across these aspects in long-form GDDs. We introduce A2Z GameSpec-Bench, a benchmark of 100 long-form GDDs for evaluating end-to-end game development by agents. We measure faithfulness by checking whether the game satisfies the GDD requirements and preserves the relationships among them. Each GDD is turned into a dependency-aware contract that contains rules, constraints, a"},{"upvotes":3,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Guanqun Yang","Wenlong Zhang","Tian Shi","Ping Wang"],"url":"https://arxiv.org/abs/2609.38822","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.38822","topics":["Evaluation"],"source":"hf","title":"SkillSeek: Revisiting Agent Skill Retrieval at Marketplace Scale","pdf":"https://arxiv.org/pdf/2609.38822.pdf","tags":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.38822","id":"arxiv:2609.38822","abstract":"Anthropic's Agent Skills package reusable procedural know-how for an LLM agent into SKILL.md directories, and open-source aggregations have grown past 230,000 skills, making selection rather than authoring the bottleneck. The standing answer in the literature outsources selection to the agent itself: an LLM-mediated retrieval loop that rewrites queries and refines candidates inside the agent's decision loop, paying LLM tokens on every task. We present SkillSeek, an open-source two-stage skill retriever built from the standard IR recipe (a BGE-base bi-encoder feeding a small cross-encoder, exposed over MCP). Across a $4 \\times 11$ grid of pool, backbone, and method on the 89-task SkillsBench benchmark, SkillSeek reaches observed parity with the LLM-mediated loop of Liu et al. at essentially no extra cost: plain bm25 alone records a pass rate at or above their refined loop on three of four"},{"upvotes":1,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Muhammad Huzaifa","Sina Mavali","Thorsten Eisenhofer"],"url":"https://arxiv.org/abs/2609.39788","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39788","topics":["LLM Training","Multi-Agent","Evaluation","Alignment"],"source":"hf","title":"Safety of Latent Communication in Multi-Agent Systems","pdf":"https://arxiv.org/pdf/2609.39788.pdf","tags":["LLM Training","Multi-Agent","Evaluation","Alignment"],"hfUrl":"https://huggingface.co/papers/2609.39788","id":"arxiv:2609.39788","abstract":"Latent communication enables multi-agent systems to exchange information directly in internal representation space, reducing the token, computation, and latency overhead of text-based communication. To this end, lightweight trainable links are introduced to map the sender's representations into the receiver's input space. In this work, we show that even benign link training can increase harmful compliance relative to text-based communication while the underlying safety-aligned agents remain unchanged. An attacker can amplify this effect by optimizing the links on harmful query--response pairs or poisoning otherwise benign training data. We further develop a reinforcement-learning attack that rewards harmful compliance alongside benign task performance without requiring harmful target responses. Across three communication topologies and four safety benchmarks, this attack raises the mean "},{"upvotes":1,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Yiduo Jia","Muzhi Zhu","Jinchuan Shi","Hao Zhong","Yuling Xi","Ke Liu","Hao Chen"],"url":"https://arxiv.org/abs/2609.40048","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.40048","topics":["VLM Training","Reasoning","Planning","Evaluation"],"source":"hf","title":"CoEvoWhen: Policy-Tool Coevolution for Ultra-Long Video Temporal Grounding","pdf":"https://arxiv.org/pdf/2609.40048.pdf","tags":["VLM Training","Reasoning","Planning","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.40048","id":"arxiv:2609.40048","abstract":"Ultra-long video temporal grounding requires balancing long-range evidence search with fine-grained event understanding under a limited visual budget, yet existing agentic methods still rely largely on predefined policies and tool capabilities. Motivated by this, we propose a novel policy-tool coevolution framework that jointly evolves high-level policies and executable media tools from the agentic reasoning trajectories of a VLM, forming a reusable skill without updating model parameters. During evolution, an external skill updater distills transferable task experience in long-video temporal grounding, accordingly refining the orchestration of long-range image-based and fine-grained video-based observations. Alongside these policy updates, the updater employs its coding capabilities to upgrade existing tools or create new ones, adapting the tools to long-video evidence acquisition. Equi"},{"upvotes":1,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Kaixuan Fan","Kaituo Feng","Tianshuo Peng","Yilei Jiang","Manyuan Zhang","Junke Wang","Xiangyu Yue"],"url":"https://arxiv.org/abs/2609.40230","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.40230","topics":["LLM Training","Evaluation","Fine-tuning"],"source":"hf","title":"EviRover: Reinforcing Agentic Perception Beyond a Glance","pdf":"https://arxiv.org/pdf/2609.40230.pdf","tags":["LLM Training","Evaluation","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2609.40230","id":"arxiv:2609.40230","abstract":"Visual perception is conventionally formulated as a one-shot prediction from a single glance at the image, under the assumption that the image content and the model's parametric knowledge suffice to resolve the query. This assumption often fails in real-world scenarios that hinge on fine-grained visual details or require knowledge-intensive and up-to-date information. We term such cases \\textit{perception under insufficient evidence} and formulate perception as an agentic process that can obtain information beyond a single glance. To address the absence of data for this setting, we design two dedicated data generation pipelines, yielding EviRover-SFT-5K and EviRover-RL-12K for training. We further construct EviLens, a human-verified benchmark comprising 688 instances across five perception categories. Building on these data, we present EviRover, to our knowledge the first perception agen"},{"upvotes":25,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Merkourios Simos","Chengkun Li","Bianca Ziliotto","Alexander Mathis"],"url":"https://arxiv.org/abs/2609.38653","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38653","topics":["Evaluation"],"source":"arxiv","title":"TERRA: Terrain-Aware Reconstruction, Retargeting and Control for Musculoskeletal Locomotion","pdf":"https://arxiv.org/pdf/2609.38653.pdf","tags":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.38653","id":"arxiv:2609.38653","abstract":"Recent advances in musculoskeletal modeling and reinforcement learning have enabled muscle-actuated agents to reproduce increasingly complex human motions. Yet these capabilities remain largely confined to flat ground, in part because motion datasets rarely include aligned terrain geometry and because retargeting terrain interactions to complex musculoskeletal bodies is challenging. We present TERRA, an end-to-end pipeline for terrain-aware retargeting and control of musculoskeletal locomotion. From kinematic trajectories alone, TERRA combines terrain priors, estimated contacts, and negative free-space evidence to recover task-relevant support geometry. TERRA further considers anatomical, tendon-continuity, and contact constraints during retargeting. Using the resulting motion-terrain pairs from five datasets, we successfully train a single muscle-actuated control policy on 9.4 hours of "},{"upvotes":4,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Prithwish Jana","Mononito Goswami","Hao Liu","Xinyu Li","Langlin Huang","Zhehui Huang","Zhishen Huang","Patrick Blöbaum","Anoop Deoras","Purak Jain","Nikos Kanakaris","Sahika Genc"],"url":"https://arxiv.org/abs/2609.38349","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38349","topics":["Multi-Agent","Evaluation"],"source":"arxiv","title":"MILO: Automated Harness Discovery via Orchestrated Multi-Agent Evolution","pdf":"https://arxiv.org/pdf/2609.38349.pdf","tags":["Multi-Agent","Evaluation"],"hfUrl":"https://huggingface.co/papers/2609.38349","id":"arxiv:2609.38349","abstract":"Modern agentic systems combine an AI model with a harness that controls execution and environmental interactions. Harness design strongly affects long-horizon performance, yet its combinatorial search space demands substantial human effort that must be repeated as models change. Existing automated methods explore this space narrowly, optimizing only components such as prompts or skills or becoming trapped by fixed, exploitative search strategies. We introduce MILO (Meta-evolutionary Island Orchestration), a framework that co-evolves agent harnesses and the strategy used to discover them. MILO combines: (i) hierarchical lineage memory over island-based trees, using rejected mutations as negative evidence; (ii) per-island mutator agents that rewrite complete harnesses using global search history and parent-specific feedback; and (iii) an orchestrator that adapts search through lineage graf"},{"upvotes":2,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Hanwen Liu","Yuanfu Sun","Qiaoyu Tan"],"url":"https://arxiv.org/abs/2609.39154","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39154","topics":["Agentic Search","Post-Training","Multi-Agent","Planning","Agent Framework"],"source":"arxiv","title":"DAGent: Evaluate-then-Grow Planning for Deep Research Agents","pdf":"https://arxiv.org/pdf/2609.39154.pdf","tags":["Agentic Search","Post-Training","Multi-Agent","Planning","Agent Framework"],"hfUrl":"https://huggingface.co/papers/2609.39154","id":"arxiv:2609.39154","abstract":"Deep research tasks require agents to navigate large knowledge spaces, synthesize evidence across many sources, and adapt their plans as findings emerge. Directed acyclic graph (DAG)-based multi-agent systems suit this setting because they support parallel execution and isolate each sub-task within a focused dependency context. Yet existing DAG-based agents instantiate a task-level plan before execution and repair the graph only after failures or missing evidence are observed. This Plan-then-Patch strategy is brittle for deep research: the system commits most strongly when its evidence is weakest, and later revisions waste computation on branches that should not have been planned. We propose DAGent, a DAG-based multi-agent framework with Evaluate-then-Grow incremental planning: an Orchestrator grows the task graph one batch at a time, conditioning each expansion on confidence and uncerta"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Tianyu Chen","Mingyuan Zhou","Jiaxing Wu"],"url":"https://arxiv.org/abs/2609.38743","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.38743","topics":["Agentic Search","LLM Training","Planning","Evaluation","Fine-tuning","Multimodal Agent","RL for LLM"],"source":"arxiv","title":"Learning to Route in Visual Space via Multi-Step Embedding Retrieval","pdf":"https://arxiv.org/pdf/2609.38743.pdf","tags":["Agentic Search","LLM Training","Planning","Evaluation","Fine-tuning"],"id":"arxiv:2609.38743","abstract":"LLM agents rely on retrieval tools to access external knowledge, yet visual agentic search remains severely bottlenecked by standard single-step retrievers. In current pipelines, the agent must issue text queries for every intermediate step, struggling when visual clues are difficult to describe or when the retriever fails to surface necessary intermediate evidence within its top results. We hypothesize that offloading multi-step navigation across the entire embedding space directly to the retrieval tool resolves this performance bottleneck. To study this systematically, we introduce VHOP, a flexible data generation framework and benchmark with five core difficulty levels testing both visual matching and search planning. Using this framework, we develop VHOP-Router, an end-to-end training pipeline---combining supervised fine-tuning, online imitation learning, and reinforcement learning--"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Minye Shao","Chaohui Yu","Yixuan Wu","Fan Wang","Ling Shao","Yang Long"],"url":"https://arxiv.org/abs/2609.39566","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39566","topics":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"source":"arxiv","title":"From Given to Gathered Evidence: Agentic Learning for Longitudinal Medical Reasoning","pdf":"https://arxiv.org/pdf/2609.39566.pdf","tags":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation"],"id":"arxiv:2609.39566","abstract":"Foundation models can serve as clinical agents through tool-use harnesses. However, conventional medical benchmarks assess reasoning over preselected evidence rather than the ability to seek it across clinical records and longitudinal imaging. We propose CASE: a series of role-specific Clinical Agents for Seeking Evidence, together with a tool-use harness and an agentic post-training framework for compact vision-language policy models. We further introduce a longitudinal multimodal benchmark built on UK Biobank, comprising 50,401 clinical questions derived from real-world ICD-10-coded diagnoses of 4,739 participants. Each question links to a patient-specific environment containing clinical context and multi-sequence MRI from baseline and follow-up visits, where agents autonomously select which visits, organs, modalities, slices, and specialist tools to inspect and compare. Supervised fin"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Chenyangguang Zhang","Malgorzata Gwiazda","Guanlong Jiao","Yuanchen Ju","Federico Tombari","Koushil Sreenath","Marc Pollefeys","Sunghwan Hong"],"url":"https://arxiv.org/abs/2609.39665","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39665","topics":["LLM Training","VLM Training","Reasoning","Planning","Fine-tuning","Data Engine"],"source":"arxiv","title":"ChronoGraph: Functional 4D Scene Graphs with Vision-Language Models for Interaction Understanding and Grounded Planning","pdf":"https://arxiv.org/pdf/2609.39665.pdf","tags":["LLM Training","VLM Training","Reasoning","Planning","Fine-tuning"],"id":"arxiv:2609.39665","abstract":"Embodied agents must determine where to act, anticipate the resulting scene changes, and interpret observed outcomes to guide subsequent actions. This requires connecting 4D interaction understanding, which explains how past actions changed the scene, with spatially grounded planning, which determines how and where to act toward a goal and anticipates the resulting scene changes. We introduce ChronoGraph, a functional 4D scene graph that links actions on affordance parts to semantic and geometric state changes. By representing observed and anticipated transitions in the same form, it provides a shared basis for understanding and planning. We construct ChronoGraphBench through an automatic data engine that converts human-interaction videos and simulated robot trajectories into graph-annotated questions for training and evaluating Vision-Language Models (VLMs) on both tasks. Using these an"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Qize Yu","Lianrui Fan","Boyu Chen","Jiaqi Liang","Xini Ding","Yue Chen","Zetian Song","Yuran Wang","Yi Zou","Kaixuan Wang","Tianxing Chen","Wenxuan Song","Bohan Zhou","Mingleyang Li","Siqiao Huang","Yuqi Ye","Caigao Jiang","Wei Wei","Ruihai Wu","Hang Zhang","Yixiao Ge","Shuchang Zhou","Shilong Liu","Xianming Liu","Ping Luo","Shiyu Huang"],"url":"https://arxiv.org/abs/2609.39601","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39601","topics":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning","Data Engine"],"source":"arxiv","title":"GroundingPI: A Grounding Foundation Model towards Physical Intelligence with Visual Primitives","pdf":"https://arxiv.org/pdf/2609.39601.pdf","tags":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning"],"id":"arxiv:2609.39601","abstract":"Precise grounding matters. It specifies which object is the target and where that object is, even in clutter and for tiny objects, and it has to be fast enough for closed-loop control. Yet vision-language-action (VLA) and world-action models (WAMs) take perception from general-purpose vision-language and video-generation backbones, which still fail in these settings. We introduce GroundingPI, a 4B grounding foundation model that generates points and boxes as quantized coordinates in a shared vocabulary. Training combines multimodal and spatial pretraining, supervised fine-tuning, and reinforcement learning with GRPO, using supervision from public datasets and dedicated data engines. Against 44 baselines across 34 grounding benchmarks spanning 11 perceptual capabilities, GroundingPI establishes a new state of the art, averaging 73.68%, above the larger GPT-6 Astra (71.54%). As a downstrea"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Qize Yu","Lianrui Fan","Bowen Ping","Xini Ding","Zetian Song","Junbo Niu","Kaixuan Wang","Tianxing Chen","Yue Chen","Minghua He","Yuran Wang","Jie Huang","Haojun Zhang","Min Chen","Hao Li","Wenxuan Song","Ruihai Wu","Xianming Liu","Shilong Liu","Shuchang Zhou","Ping Luo","Shiyu Huang"],"url":"https://arxiv.org/abs/2609.39600","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39600","topics":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning","Data Engine"],"source":"arxiv","title":"GroundAnything: Reconciling Parallel Decoding with Precise Visual Grounding at Flash Speed","pdf":"https://arxiv.org/pdf/2609.39600.pdf","tags":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning"],"id":"arxiv:2609.39600","abstract":"Autoregressive (AR) grounding models serialize spatial predictions, introducing sequential latency and imposing a causal order on output tokens. We view grounding as visual evidence extraction: objects, locations, and spatial relations are jointly constrained by the image and query, yet their dependencies do not imply an intrinsic left-to-right generation order. This distinction makes bidirectional diffusion a natural fit, allowing spatial hypotheses to emerge in parallel and be jointly refined through iterative denoising. We introduce GroundAnything, a 4B-parameter grounding foundation model that reconciles fast parallel decoding with precise localization through blockwise denoising. Training combines grounding pretraining from public datasets and dedicated data engines, direct AR-to-diffusion conversion with joint AR and diffusion objectives, supervised fine-tuning, and GRPO-based rein"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Yijie Bian","Kai Zhang","Wei Guo","Zixin Wang","Shenghui Song","Jun Zhang","Khaled B. Letaief"],"url":"https://arxiv.org/abs/2609.39964","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39964","topics":["Reasoning","Planning","Evaluation","Data Engine","Agent Framework"],"source":"arxiv","title":"AIMS: An Agentic AI Framework for Sim-to-Real Multi-Modal ISAC","pdf":"https://arxiv.org/pdf/2609.39964.pdf","tags":["Reasoning","Planning","Evaluation","Data Engine","Agent Framework"],"id":"arxiv:2609.39964","abstract":"Multi-modal integrated sensing and communication (ISAC) enables environmental perception and reliable connectivity for intelligent wireless networks. Data-driven multi-modal ISAC models depend heavily on annotated real-world data to learn relationships across sensing and wireless observations, thereby constraining scalable deployment. Although synthetic data generation reduces the burden, adapting existing simulation pipelines to a target deployment requires consistent scene, sensing, wireless, and learning configurations, while mismatches among these coupled components impair sim-to-real transferability. To address the challenge, we propose an agentic artificial intelligence (AI) framework for sim-to-real multi-modal ISAC, named AIMS. Given a natural-language deployment request specifying the target task, deployment conditions, and real-data budget, AIMS derives a deployment-specific si"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Yitong Qiao","Yancheng Jin","Lei Liu","Yue Shen","Jian Wang","Jinjie Gu","Zhixuan Chu"],"url":"https://arxiv.org/abs/2609.39371","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.39371","topics":["Agent Safety","LLM Training","Reasoning","Evaluation","Fine-tuning"],"source":"arxiv","title":"EHR-RobustGym: Benchmarking and Training Agents for Robust Clinical Reasoning","pdf":"https://arxiv.org/pdf/2609.39371.pdf","tags":["Agent Safety","LLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2609.39371","abstract":"In hospital workflows, electronic health records (EHRs) are often noisy, and may not contain the evidence needed to confirm events or measurements referenced in a clinical query. Even when database retrieval succeeds, clinical agents can overlook such discrepancies and return plausible but unsupported answers. We introduce EHR-RobustGym, a scalable and interactive environment for evaluating and training robust clinical agents grounded in noisy EHRs. Built on MIMIC-IV hospital records (365K patients, 31 tables, and over 500M records), EHR-RobustGym comprises 5,486 Clean-Noise pairs spanning six clinical intents and both patient-level and population-level queries. The pairs test robustness to Record-level, Value-level, and Query-level noise, while interactive SQL/Python execution and outcome verification support trajectory collection and training. Evaluating multiple LLMs reveals substanti"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Zhimin Gao","Pichao Wang"],"url":"https://arxiv.org/abs/2609.38850","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.38850","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"source":"arxiv","title":"OpenJev-RLCD: A Working RLCD Implementation","pdf":"https://arxiv.org/pdf/2609.38850.pdf","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"id":"arxiv:2609.38850","abstract":"Decision models such as Jev answer questions with probabilities, which are only useful if they are calibrated. Open-source reproductions rely on supervised fine-tuning plus temperature scaling, while reinforcement learning from verifiable rewards (RLVR) makes reasoning models overconfident. We present a working implementation of reinforcement learning for calibrated decisions (RLCD) for reasoning models: the model samples a rationale, and we score the answer distribution it commits to afterwards with a strictly proper scoring rule. A variance identity shows that scoring the mixture of several samples rewards disagreeing rationales, and that RLVR is exactly this mixture objective without its diversity term. Optimized naively, the per-rationale objective either switches reasoning off or is drowned out by policy-gradient noise, which leads to a two-stage recipe: calibrate, then reinforce. W"},{"upvotes":0,"announceDate":"2026-10-01","date":"2026-10-01","authors":["Anmol Kabra","Swathi Saravana Selvam","Albert Gong","Chao Wan","Christian Belardi","Dongyoung Go","Katie Z. Luo","Kilian Q. Weinberger"],"url":"https://arxiv.org/abs/2609.40221","submittedDate":"2026-09-30","arxiv":"https://arxiv.org/abs/2609.40221","topics":["Agentic Search","LLM Training","Hallucination","Evaluation","RL for LLM"],"source":"arxiv","title":"PhantomEnvironments: Training LLM Agents in Fictional Worlds","pdf":"https://arxiv.org/pdf/2609.40221.pdf","tags":["Agentic Search","LLM Training","Hallucination","Evaluation","RL for LLM"],"id":"arxiv:2609.40221","abstract":"Training LLM agents with reinforcement learning (RL) is bottlenecked by environments, which must provide verifiable rewards, support long-horizon interaction, and scale cheaply. Existing approaches rely on costly human-curated data or on LLM-generated environments that risk hallucinations and benchmark contamination. We show that LLMs can instead be trained into capable search agents using synthetic environments generated entirely by rules, whose generation requires no LLM and has zero marginal cost. We build PhantomEnvironments, multi-turn RL environments from fictional worlds, where agents must search a corpus of templated articles to answer multi-hop questions. Despite sharing no facts with the real world, these strikingly simple environments yield agents that transfer to real-world multi-hop search benchmarks, often outperforming real-world training data on newer benchmarks. Trained "}],"archive":[],"latestPath":"data/latest.json"};
